import sys,random,hashlib,math,json
sys.path.insert(0,'/workspace/submission')
from crosscheck.replay import CrossCheck,_agreement

def brute_agree(entries,eps):
    # entries (v,w), expand unique values with weights
    vals=sorted(set(v for v,w in entries if w))
    best=None
    for lo in vals:
        for hi in vals:
            if hi<lo: continue
            if 1000000*(hi-lo)<=eps*hi:
                w=sum(wt for v,wt in entries if wt and lo<=v<=hi)
                cand=(w,-lo,-hi)
                if best is None or cand>best:
                    best=cand
    w,nlo,nhi=best
    lo=-nlo;hi=-nhi
    sw=sum(wt for v,wt in entries if wt and lo<=v<=hi)
    svw=sum(v*wt for v,wt in entries if wt and lo<=v<=hi)
    return svw//sw,sw

def naive(eng):
    F=len(eng.flows);t=eng.trials;eps=eng.epsilon;seed=eng.seed
    ip,ep=eng._predictions(); routes=ip is not None
    pools=[]
    for f in eng.flows:
        p=[]
        for key in (f.source_key,f.destination_key):
            if key is not None and eng.counter_values[key] is not None:p.append(eng.counter_values[key])
        if routes:
            pred=ip.get(f.pair,0) if f.kind=='internal' else ep[f.pair]
            p.append(min(pred,f.capacity))
        pools.append(p)
    fixed={};remaining=set(range(F));order=[];linksvals={};confs={}
    while remaining:
        cands={}
        for idx in remaining:
            f=eng.flows[idx]
            entries=[(v,t) for v in pools[idx]]
            for r in f.endpoints:
                rems=[]
                for tt in range(t):
                    vals={}
                    for gi in eng.incident_by_router[r]:
                        g=eng.flows[gi]
                        if gi in fixed:v=fixed[gi]
                        else:
                            pool=pools[gi]
                            if not pool:v=0
                            else:
                                W=int.from_bytes(hashlib.sha256(f'{seed}:{r}:{tt}:{g.src}:{g.dst}'.encode()).digest()[:8],'big')
                                v=pool[W%len(pool)]
                        vals[gi]=v
                    tin=sum(v for gi,v in vals.items() if eng.flows[gi].dst==r)
                    tout=sum(v for gi,v in vals.items() if eng.flows[gi].src==r)
                    sv=vals[idx]
                    if f.src==r: rv=tin-(tout-sv)
                    else: rv=tout-(tin-sv)
                    rems.append(max(0,min(f.capacity,rv)))
                rep,mass=brute_agree([(v,1) for v in rems],eps)
                if mass: entries.append((rep,mass))
            rep,supp=brute_agree(entries,eps)
            cands[idx]=(rep,supp)
        mx=max(s for v,s in cands.values())
        idx=min(i for i in remaining if cands[i][1]==mx)
        val,supp=cands[idx]
        fixed[idx]=val;confs[idx]=supp;order.append(eng.flows[idx].pair);linksvals[idx]=val;remaining.remove(idx)
    links=[]
    for i,f in enumerate(eng.flows):
        n,d=supp if False else (confs[i],t)
        g=math.gcd(n,d);n//=g;d//=g
        links.append((f.src,f.dst,linksvals[i],n,d))
    return tuple(links),tuple(order)

def random_case(seed):
    rnd=random.Random(seed)
    n=rnd.randint(1,8)
    ids=rnd.sample(range(0,20),n)
    names=['N'+str(i) for i in range(n)]
    # random connected tree + optional edges, degree cap8
    links=[]
    for i in range(1,n):
        j=rnd.randrange(i)
        u,v=ids[i],ids[j]
        if (min(u,v),max(u,v)) not in {(min(a,b),max(a,b)) for a,b,c in links}:
            links.append((u,v,rnd.randint(0,20)))
    poss=[(ids[i],ids[j]) for i in range(n) for j in range(i+1,n)]
    rnd.shuffle(poss)
    deg={x:0 for x in ids}
    for a,b,c in links:deg[a]+=1;deg[b]+=1
    for u,v in poss:
        if rnd.random()<.2 and deg[u]<8 and deg[v]<8 and (min(u,v),max(u,v)) not in {(min(a,b),max(a,b)) for a,b,c in links}:
            links.append((u,v,rnd.randint(0,20)));deg[u]+=1;deg[v]+=1
    ext=rnd.sample(ids,rnd.randint(0,min(n,4)))
    topo={'nodes':[{'id':ids[i],'name':names[i],'external_capacity':rnd.randint(0,20)} for i in range(n)],
          'links':[{'source':a,'target':b,'capacity':c} for a,b,c in links],
          'external_nodes':[names[ids.index(x)] for x in ext]}
    eng=CrossCheck(topo)
    eng.trials=rnd.randint(1,4);eng.epsilon=rnd.choice([0,1,50000,100000,250000])
    eng.seed=rnd.randint(0,2**32-1)
    # random measured counters valid bounds
    for key in eng.counter_values:
        if rnd.random()<.8:
            eng.counter_values[key]=rnd.randint(0,eng.counter_capacity[key])
        else: eng.counter_values[key]=None
    for p in eng.demand_pairs:
        eng.demands[p]=rnd.randint(0,30)
    if rnd.random()<.7:
        # nonnull routes: direct link paths for connected external pairs maybe all via direct topology path
        # use simple graph shortest path
        adj={x:[] for x in ids}
        for a,b,c in links:adj[a].append(b);adj[b].append(a)
        lookup={}
        for s in ext:
            for d in ext:
                if s==d:continue
                # bfs
                prev={s:None};q=[s]
                for x in q:
                    if x==d:break
                    for y in adj[x]:
                        if y not in prev:prev[y]=x;q.append(y)
                if d not in prev: continue
                path=[];x=d
                while x is not None:path.append(x);x=prev[x]
                path=list(reversed(path))
                # split into 1 or 2 weighted entries maybe duplicated same path
                if rnd.random()<.5:
                    entries=[(tuple(path),1000)]
                else:
                    entries=[(tuple(path),rnd.randint(1,999))]
                    entries.append((tuple(path),1000-entries[0][1]))
                    entries.sort()
                lookup[(s,d)]=tuple(entries)
        # if all pairs covered else still nonnull incomplete is out of domain but core likely okay
        eng.has_routes=True;eng.route_lookup=lookup
    else:
        eng.has_routes=False;eng.route_lookup=None
    return eng

